runCommand:
$wsus = '{{ WsusServerUrl }}'.TrimEnd('/')
if (-not $wsus) {
    Write-Host "WsusServerUrl not provided. Using the existing Windows Update configuration."
    exit 0
}
$uri = [System.Uri]$wsus
if (-not (Test-NetConnection -ComputerName $uri.Host -Port $uri.Port -InformationLevel Quiet)) {
    throw "Cannot reach WSUS server $wsus from this instance."
}
$wu = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
if (-not (Test-Path $wu)) { New-Item -Path $wu | Out-Null }
if (-not (Test-Path "$wu\AU")) { New-Item -Path "$wu\AU" | Out-Null }
New-ItemProperty -Path $wu -Name WUServer -Value $wsus -PropertyType String -Force | Out-Null
New-ItemProperty -Path $wu -Name WUStatusServer -Value $wsus -PropertyType String -Force | Out-Null
New-ItemProperty -Path $wu -Name DoNotConnectToWindowsUpdateInternetLocations -Value 1 -PropertyType DWord -Force | Out-Null
New-ItemProperty -Path "$wu\AU" -Name UseWUServer -Value 1 -PropertyType DWord -Force | Out-Null
Restart-Service -Name wuauserv -Force
Write-Host "Windows Update Agent configured to use WSUS server $wsus"
